function verifySignature({
  body,
  signature,
}: {
  body: string
  signature: string
}) {
  const secret = process.env.GITHUB_WEBHOOKS_SECRET!
  const hash = crypto.createHmac('sha256', secret).update(body).digest('hex')
  return `sha256=${hash}` === signature
}

