// Total revenue per month for past 12 months
import { prisma } from '@/lib/prisma'

export async function getMonthlyRevenue() {

output:
    const currentDate = new Date();
    const startDate = new Date(currentDate.getFullYear(), currentDate.getMonth() - 12, 1);

    const monthlyRevenues = await prisma.order.findMany({
        where: {
            createdAt: {
                gte: startDate,
            },
            status: 'PAID',
        },
        select: {
            id: true,
            createdAt: true,
        }
    });

    const monthlyRevenue = Array.from({ length: 12 }).map((_, index) => {
        const monthStartDate = new Date(currentDate.getFullYear(), currentDate.getMonth() - index, 1);
        const monthEndDate = new Date(currentDate.getFullYear(), currentDate.getMonth() - index + 1, 0);

        const revenue = monthlyRevenues.reduce((total, order) => {
            if (order.createdAt >= monthStartDate && order.createdAt <= monthEndDate) {
                return total + 1;
            }
            return total;
        }, 0);

        const formattedMonth = new Intl.DateTimeFormat('en-US', { month: 'long' }).format(monthStartDate);

        return { name: formattedMonth, total: revenue };
    });

    return monthlyRevenue;
}

  const data = await fetch(
    "https://api.github.com/repos/vercel/next.js",
    { next: { revalidate: 60 } },
  ).then((res) => res.json());

  return (
    <div className="card">
      <h2>Analytics</h2>
      <p>Stargazers: {data.stargazers_count}</p>
